input.command:
node -e '
const fs=require("fs");
let raw=fs.readFileSync("/tmp/terms.html","utf8");
raw=raw.replace(/<script[\s\S]*?<\/script>/g," ").replace(/<style[\s\S]*?<\/style>/g," ");
let txt=raw.replace(/<[^>]+>/g,"\n");
txt=txt.replace(/&amp;/g,"&").replace(/&quot;/g,"\"").replace(/&#x27;|&#39;|&rsquo;/g,"\x27").replace(/&nbsp;/g," ").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&ldquo;|&rdquo;/g,"\"");
txt=txt.replace(/\n\s*\n+/g,"\n");
fs.writeFileSync("/tmp/terms.txt",txt);
console.log(txt.length);
'
